(function(){if(!('IntersectionObserver'in window))return;function load(v){if(v.dataset.cachingoutLoaded)return;v.dataset.cachingoutLoaded='1';if(v.dataset.src){v.src=v.dataset.src;v.removeAttribute('data-src')}v.querySelectorAll('source[data-src]').forEach(function(s){s.src=s.dataset.src;s.removeAttribute('data-src')});v.preload='auto';try{v.load()}catch(e){}}
var vo=new IntersectionObserver(function(es){es.forEach(function(e){var v=e.target;if(e.isIntersecting){load(v);if(v.dataset.autoplay==='1'||v.dataset.cachingoutWasPlaying==='1'){v.muted=v.muted||v.dataset.autoplay==='1';var p=v.play();if(p&&p.catch)p.catch(function(){})}}else if(!v.paused){v.dataset.cachingoutWasPlaying='1';v.pause()}else{delete v.dataset.cachingoutWasPlaying}})},{rootMargin:'200px'});
document.querySelectorAll('video[data-cachingout-video]').forEach(function(v){vo.observe(v)});
function isYT(f){return /youtube(-nocookie)?\.com\/embed\//i.test(f.src)}function isVimeo(f){return /player\.vimeo\.com\//i.test(f.src)}
var fo=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting)return;var f=e.target;try{if(isYT(f))f.contentWindow.postMessage(JSON.stringify({event:'command',func:'pauseVideo',args:''}),'*');else if(isVimeo(f))f.contentWindow.postMessage(JSON.stringify({method:'pause'}),'*')}catch(x){}})},{threshold:0});
function watch(root){(root.querySelectorAll?root.querySelectorAll('iframe'):[]).forEach(function(f){if(f.dataset.cachingoutWatched)return;if(isYT(f)||isVimeo(f)){f.dataset.cachingoutWatched='1';fo.observe(f)}})}
watch(document);if('MutationObserver'in window){new MutationObserver(function(ms){ms.forEach(function(m){m.addedNodes.forEach(function(n){if(n.nodeType===1){if(n.tagName==='IFRAME'){watch({querySelectorAll:function(){return[n]}})}else{watch(n)}}})})}).observe(document.body,{childList:true,subtree:true})}})();
